# Links in a full mesh = n(n-1)/2 ; links in a star = n

def mesh_links(n):
    return n * (n - 1) // 2

def star_links(n):
    return n

print("Devices  Star  Full mesh")
for n in [3, 4, 6, 10, 20, 30, 50]:
    print(f"{n:7}  {star_links(n):4}  {mesh_links(n):9}")

